/**
 * Reader for the CI-generated public/prices.json snapshot.
 *
 * The deployed site is a static bundle and the upstream providers send no CORS
 * headers, so this file is the only trustworthy source of prices at runtime.
 * It is generated by scripts/fetchPrices.mjs in .github/workflows/deploy.yml.
 *
 * Everything here is snapshot-only: no value is ever synthesised, so a missing
 * or stale snapshot surfaces as `null` and the UI can say so honestly.
 */

const SNAPSHOT_URL = `${import.meta.env.BASE_URL}prices.json`;

/** Treat a snapshot older than this as not current, regardless of source. */
export const STALE_AFTER_MS = 60 * 60 * 1000;

let snapshotPromise = null;
let snapshot = null;

async function loadSnapshot() {
  if (snapshot) return snapshot;
  if (snapshotPromise) return snapshotPromise;

  snapshotPromise = (async () => {
    try {
      const response = await fetch(SNAPSHOT_URL, { cache: 'no-cache' });
      if (!response.ok) return null;
      const data = await response.json();
      if (!data || typeof data !== 'object' || !data.quotes) return null;
      return {
        generatedAt: data.generatedAt || null,
        provider: data.provider || null,
        quotes: data.quotes || {},
        history: data.history || {},
        errors: data.errors || {}
      };
    } catch {
      return null;
    }
  })()
    .then(data => {
      snapshot = data;
      return data;
    })
    .finally(() => {
      snapshotPromise = null;
    });

  return snapshotPromise;
}

export function getSnapshot() {
  return snapshot;
}

export function invalidateSnapshot() {
  snapshot = null;
}

/**
 * Real quote for a Yahoo symbol, or null when the snapshot has no entry.
 */
export function getQuote(symbol) {
  const entry = snapshot?.quotes?.[symbol];
  if (!entry || !Number.isFinite(entry.price)) return null;
  return { ...entry, source: snapshot.provider || 'Yahoo Finance', asOf: snapshot.generatedAt || null };
}

/**
 * Real daily history for a Yahoo symbol as chart-ready rows, or an empty array.
 * Column-oriented storage is expanded here so callers keep their existing shape.
 */
export function getHistory(symbol) {
  const series = snapshot?.history?.[symbol];
  if (!series || !Array.isArray(series.close) || series.close.length === 0) return [];

  const rows = [];
  for (let i = 0; i < series.close.length; i++) {
    const close = series.close[i];
    if (!Number.isFinite(close)) continue;
    rows.push({
      date: new Date(series.dates[i]),
      open: Number.isFinite(series.open?.[i]) ? series.open[i] : close,
      high: Number.isFinite(series.high?.[i]) ? series.high[i] : close,
      low: Number.isFinite(series.low?.[i]) ? series.low[i] : close,
      close,
      volume: series.volume?.[i] ?? null
    });
  }
  return rows;
}

export function hasHistory(symbol) {
  return getHistory(symbol).length > 0;
}

/** Tail of a snapshot history series, aligned by index across symbols. */
export function getSeries(symbol, field = 'close') {
  const series = snapshot?.history?.[symbol];
  return Array.isArray(series?.[field]) ? series[field] : [];
}

export function snapshotAgeMs() {
  if (!snapshot?.generatedAt) return null;
  const generatedAt = Date.parse(snapshot.generatedAt);
  return Number.isFinite(generatedAt) ? Date.now() - generatedAt : null;
}

export function isSnapshotStale() {
  const age = snapshotAgeMs();
  return age == null || age > STALE_AFTER_MS;
}

export { loadSnapshot };
